<script setup>
import {computed,ref} from 'vue'
import {useData} from 'vitepress'
import data from '../../data/requirements.json'
const {frontmatter}=useData(),lang=computed(()=>frontmatter.value.locale==='en'?'en':'zh-CN'),english=computed(()=>lang.value==='en')
const epic=ref('ALL'),state=ref('ALL'),query=ref('')
const epics={CLUSTER:['统一控制','Cluster control'],SESSION:['浏览器会话','Sessions'],RECOVERY:['人工恢复','Manual recovery'],SOURCE:['源端兼容','Source compatibility'],JAVA:['Java 运行时','Java runtimes'],DOCS:['完整文档','Documentation'],CARRYOVER:['历史范围','Carryover']}
const counts=computed(()=>Object.fromEntries(['DONE','PARTIAL','NEW'].map(s=>[s,data.requirements.filter(r=>r.status===s).length])))
const rows=computed(()=>data.requirements.filter(r=>(epic.value==='ALL'||r.epic===epic.value)&&(state.value==='ALL'||r.status===state.value)&&`${r.id} ${r.title[lang.value]} ${r.gap[lang.value]}`.toLowerCase().includes(query.value.toLowerCase())))
</script>
<template><div class="roadmap-summary"><div><strong>{{data.requirements.length}}</strong><span>{{english?'Requirements':'需求总数'}}</span></div><div v-for="s in ['DONE','PARTIAL','NEW']" :key="s"><strong>{{counts[s]}}</strong><span>{{s}}</span></div></div><p class="snapshot-label">{{data.specId}} · v{{data.version}} · {{data.date}} · {{data.state}}</p><div class="catalog-controls"><label>{{english?'Direction':'需求方向'}}<select v-model="epic"><option value="ALL">{{english?'All directions':'全部方向'}}</option><option v-for="(name,key) in epics" :key="key" :value="key">{{name[english?1:0]}}</option></select></label><label>{{english?'State':'状态'}}<select v-model="state"><option value="ALL">{{english?'All states':'全部状态'}}</option><option v-for="s in ['DONE','PARTIAL','NEW']" :key="s">{{s}}</option></select></label><label class="grow">{{english?'Find requirement':'查找需求'}}<input v-model="query" type="search" placeholder="CP-03 / MySQL / 会话…"></label></div><p class="result-summary" aria-live="polite">{{rows.length}} {{english?'matching requirements':'项匹配需求'}}</p><details v-for="r in rows" :key="r.id" class="requirement-item"><summary><code>{{r.id}}</code><strong>{{r.title[lang]}}</strong><span class="priority-chip">{{r.priority}}</span><span class="state-chip" :class="r.status.toLowerCase()">{{r.status}}</span></summary><p><b>{{english?'Current gap / scope: ':'当前差距 / 已记录范围：'}}</b>{{r.gap[lang]}}</p><p><b>{{english?'Acceptance: ':'验收条件：'}}</b>{{r.acceptance[lang]}}</p><p v-if="r.dependsOn.length"><b>{{english?'Dependencies: ':'依赖：'}}</b>{{r.dependsOn.join('、')}}</p><p v-if="r.verification?.archive"><a :href="'/docs/zh/evidence/'+r.verification.archive.split('/')[2]+'.html'">{{english?'Recorded evidence':'查看记录的验收证据'}} →</a></p></details><p v-if="!rows.length">{{english?'No matching requirements.':'没有匹配需求，请调整筛选。'}}</p></template>
